package com.vaultor.vaultor;

import com.vaultor.vaultor.service.*;
import com.vaultor.vaultor.service.OrganizationService.*;
import com.vaultor.vaultor.service.CollectionDeletionService.*;
import com.vaultor.vaultor.repository.ResourceRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.AfterEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@SpringBootTest
class CollectionDeletionTest {
 static final Path DATA;
 static {try{DATA=Files.createTempDirectory("vaultor-recursive-delete-");}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:sqlite:"+DATA.resolve("app.db"));p.add("app.storage.path",()->DATA.resolve("files").toString());p.add("app.host.path",()->DATA.resolve("host").toString());}
 @Autowired OrganizationService org;
 @Autowired CollectionDeletionService deletion;
 @Autowired ResourceService resources;
 @Autowired TagService tags;
 @Autowired ResourceRepository repository;
 @Autowired WorkspaceIdentityService identity;
 @Autowired JdbcTemplate jdbc;
 @MockitoSpyBean ResourceLifecycleService lifecycle;
 @MockitoSpyBean FileStorageService files;
 @AfterEach void resetSpies(){reset(lifecycle,files);}
 String collection(String parent){return org.createOnce(UUID.randomUUID().toString(),new CreationInput(UUID.randomUUID().toString(),List.of(),parent)).id();}
 com.vaultor.vaultor.model.Resource r(String id){return repository.findById(id).orElseThrow();}
 String note(){return resources.createNote("Original","{\"type\":\"doc\",\"content\":[]}").getId();}
 void add(String resource,String collection){org.bulk(new BulkInput(List.of(resource),"collection",collection,"add"));}
 Input input(Plan plan,String mode){var revisions=new TreeMap<String,String>();if(mode.equals("trash-exclusive"))for(var r:plan.exclusiveResources())revisions.put(r.id(),r(r.id()).getRevision());return new Input(plan.fingerprint(),mode,revisions);}
 Result apply(String root,String mode){return deletion.apply(root,UUID.randomUUID().toString(),input(deletion.plan(root),mode));}
 void absent(String root){assertThrows(NoSuchElementException.class,()->org.get(root));}
 @Test void emptyRootHasReceiptAndNoResources(){var root=collection(null);assertEquals(1,deletion.plan(root).collections().size());assertTrue(apply(root,"keep").trashedResourceIds().isEmpty());absent(root);}
 @Test void nestedHierarchyAndMultipleInsideMembershipsCountOneOriginal(){var root=collection(null);var child=collection(root);var leaf=collection(child);var n=note();add(n,root);add(n,leaf);assertEquals(1,deletion.plan(root).managedResources());assertEquals(0,deletion.plan(root).sharedResources());assertEquals(List.of(n),apply(root,"trash-exclusive").trashedResourceIds());absent(child);absent(leaf);assertNotNull(r(n).getTrashedAt());}
 @Test void keepPreservesContentsPinsTagsAndOutsideMembership(){var root=collection(null);var child=collection(root);var outside=collection(null);var n=note();add(n,child);add(n,outside);jdbc.update("update resources set favorite=1 where id=?",n);tags.addTagToResource(n,"retain-me");var exclusive=note();add(exclusive,root);var before=r(n);apply(root,"keep");var after=r(n);assertEquals(before.getContent(),after.getContent());assertEquals(before.getRevision(),after.getRevision());assertTrue(after.getFavorite());assertNull(after.getTrashedAt());assertEquals(1,org.get(outside).count());assertNull(r(exclusive).getTrashedAt());assertEquals(1,jdbc.queryForObject("select count(*) from resource_tags where resource_id=?",Long.class,n));}
 @Test void trashExclusiveKeepsSharedOriginalAndRestoreDoesNotRecreateCollections(){var root=collection(null);var child=collection(root);var outside=collection(null);var shared=note();var exclusive=note();add(shared,root);add(shared,child);add(shared,outside);add(exclusive,child);var p=deletion.plan(root);assertEquals(2,p.managedResources());assertEquals(1,p.sharedResources());assertEquals(List.of(exclusive),apply(root,"trash-exclusive").trashedResourceIds());assertNull(r(shared).getTrashedAt());var trashed=r(exclusive);assertEquals("restored",lifecycle.apply(new ResourceLifecycleService.Item(UUID.randomUUID().toString(),exclusive,"restore",trashed.getRevision())).status());absent(root);assertNull(r(exclusive).getTrashedAt());}
 @Test void failureAfterLifecycleMutationRollsBackEverythingIncludingReceipts(){var root=collection(null);var n=note();add(n,root);var p=deletion.plan(root);var request=input(p,"trash-exclusive");var id=UUID.randomUUID().toString();doAnswer(call->{call.callRealMethod();throw new IllegalStateException("Injected after lifecycle mutation");}).when(lifecycle).apply(any());assertThrows(IllegalStateException.class,()->deletion.apply(root,id,request));assertEquals(1,org.get(root).count());assertNull(r(n).getTrashedAt());assertEquals(0,jdbc.queryForObject("select count(*) from collection_deletions where id=?",Long.class,id));reset(lifecycle);assertEquals(List.of(n),deletion.apply(root,id,request).trashedResourceIds());}
 @Test void workspaceGenerationInvalidatesPlansAndOldReceipts(){var root=collection(null);var old=input(deletion.plan(root),"keep");var other=collection(null);var done=input(deletion.plan(other),"keep");var operation=UUID.randomUUID().toString();deletion.apply(other,operation,done);identity.replaced();assertThrows(ResponseStatusException.class,()->deletion.apply(root,UUID.randomUUID().toString(),old));assertThrows(ResponseStatusException.class,()->deletion.apply(other,operation,done));assertNotNull(org.get(root));}
 @Test void lateReceiptFailureRollsBackRemovedCollectionsMembershipsAndTrash(){var root=collection(null);var child=collection(root);var n=note();add(n,child);var request=input(deletion.plan(root),"trash-exclusive");var id=UUID.randomUUID().toString();jdbc.execute("create trigger fail_collection_deletion before insert on collection_deletions begin select raise(abort,'Injected receipt failure'); end");try{assertThrows(RuntimeException.class,()->deletion.apply(root,id,request));}finally{jdbc.execute("drop trigger fail_collection_deletion");}assertNotNull(org.get(root));assertEquals(1,org.get(child).count());assertNull(r(n).getTrashedAt());assertEquals(0,jdbc.queryForObject("select count(*) from collection_deletions where id=?",Long.class,id));assertEquals(List.of(n),deletion.apply(root,id,request).trashedResourceIds());}
 @Test void changedSubtreeInvalidatesDestructivePlan(){var root=collection(null);var old=input(deletion.plan(root),"trash-exclusive");collection(root);assertThrows(ResponseStatusException.class,()->deletion.apply(root,UUID.randomUUID().toString(),old));assertNotNull(org.get(root));}
 @Test void outsideMembershipAddedAfterConfirmationCannotTrashSharedResource(){var root=collection(null);var outside=collection(null);var n=note();add(n,root);var old=input(deletion.plan(root),"trash-exclusive");add(n,outside);assertThrows(ResponseStatusException.class,()->deletion.apply(root,UUID.randomUUID().toString(),old));assertNull(r(n).getTrashedAt());assertEquals(1,org.get(root).count());}
 @Test void uncertainResponseRetryReturnsSameReceiptAndRejectsChangedInput(){var root=collection(null);var n=note();add(n,root);var request=input(deletion.plan(root),"trash-exclusive");var id=UUID.randomUUID().toString();var result=deletion.apply(root,id,request);assertEquals(result,deletion.apply(root,id,request));assertThrows(ResponseStatusException.class,()->deletion.apply(root,id,new Input(request.fingerprint(),"keep",Map.of())));verify(lifecycle,times(1)).apply(any());}
 @Test void linkedReferencesOnlyLoseMembershipAndNeverTouchFilesystem() throws Exception {var root=collection(null);var n=resources.createNote("Linked","{\"type\":\"doc\",\"content\":[]}");var physical=DATA.resolve(UUID.randomUUID()+".md");Files.writeString(physical,"private external document");jdbc.update("update resources set type='linked',content=? where id=?","{\"type\":\"linkedDocument\",\"version\":1}",n.getId());add(n.getId(),root);assertEquals(1,deletion.plan(root).linkedReferences());assertEquals(0,deletion.plan(root).managedResources());assertTrue(apply(root,"trash-exclusive").trashedResourceIds().isEmpty());assertNull(r(n.getId()).getTrashedAt());assertEquals("private external document",Files.readString(physical));verifyNoInteractions(files);}
 @Test void staleResourceRevisionRollsBackAndDelayedSaveCannotResurrectTrash(){var root=collection(null);var n=note();add(n,root);var request=input(deletion.plan(root),"trash-exclusive");var old=r(n);resources.updateNote(n,"Edited",old.getContent(),"\""+old.getRevision()+"\"");assertThrows(RuntimeException.class,()->deletion.apply(root,UUID.randomUUID().toString(),request));assertNotNull(org.get(root));var fresh=r(n);apply(root,"trash-exclusive");assertThrows(RuntimeException.class,()->resources.updateNote(n,"Late",fresh.getContent(),"\""+fresh.getRevision()+"\""));assertNotNull(r(n).getTrashedAt());}
 @Test void managedFilesRetainBytesPinsTagsAndRestoreWhileSharedFilesStayActive() throws Exception {var root=collection(null);var outside=collection(null);var exclusive=resources.uploadFile(new org.springframework.mock.web.MockMultipartFile("file","exclusive.txt","text/plain","original file bytes".getBytes(java.nio.charset.StandardCharsets.UTF_8)));var shared=resources.uploadFile(new org.springframework.mock.web.MockMultipartFile("file","shared.txt","text/plain","shared file bytes".getBytes(java.nio.charset.StandardCharsets.UTF_8)));add(exclusive.getId(),root);add(shared.getId(),root);add(shared.getId(),outside);tags.addTagToResource(exclusive.getId(),"retain-file-tag");jdbc.update("update resources set favorite=1 where id=?",exclusive.getId());var path=files.getFile(exclusive.getFilePath());clearInvocations(files);assertEquals(List.of(exclusive.getId()),apply(root,"trash-exclusive").trashedResourceIds());assertEquals("original file bytes",Files.readString(path));assertTrue(r(exclusive.getId()).getFavorite());assertEquals(1,jdbc.queryForObject("select count(*) from resource_tags where resource_id=?",Long.class,exclusive.getId()));assertNull(r(shared.getId()).getTrashedAt());verifyNoInteractions(files);assertEquals("restored",lifecycle.apply(new ResourceLifecycleService.Item(UUID.randomUUID().toString(),exclusive.getId(),"restore",r(exclusive.getId()).getRevision())).status());assertEquals("original file bytes",Files.readString(path));}
 @Test void savedReferenceImpactIncludesSurvivingSharedSources(){var root=collection(null);var outside=collection(null);var target=note();var source=note();add(target,root);add(source,root);add(source,outside);var link="{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\",\"content\":[{\"type\":\"resourceLink\",\"attrs\":{\"resourceId\":\""+target+"\",\"label\":\"Target\",\"type\":\"note\"}}]}]}";resources.updateNote(source,"Source",link);assertEquals(1,deletion.plan(root).referringNotes());}
 @Test void realisticDocumentationHierarchyHasDistinctCountsAndAtomicRemoval(){var root=collection(null);var children=new ArrayList<String>();for(int i=0;i<14;i++)children.add(collection(i==0?root:children.get((i-1)/2)));var outside=collection(null);for(int i=0;i<204;i++){var n=note();add(n,children.get(i%14));if(i%3==0)add(n,root);if(i<7)add(n,outside);}var p=deletion.plan(root);assertEquals(15,p.collections().size());assertEquals(204,p.managedResources());assertEquals(7,p.sharedResources());assertEquals(197,apply(root,"trash-exclusive").trashedResourceIds().size());assertEquals(7,org.get(outside).count());for(var c:children)absent(c);}
}
